from pathlib import Path
from datetime import datetime
from itertools import combinations
import csv

import yaml
import numpy as np
from PIL import Image
import torch
from transformers import AutoImageProcessor, AutoModel

import matplotlib
matplotlib.use("Agg")  # headless backend (saves to file)
import matplotlib.pyplot as plt

# ============================================================
# SETTINGS
# ============================================================

# Path to the YOLO dataset (generated by prepare_yolo_dataset.py)
DATA_YAML = Path(
    "dataset_yolo/data.yaml"
)

# Folder where results will be saved
PROJECT_DIR = Path(
    "runs_embedding"
)

# ------------------------------------------------------------
# EMBEDDING EXTRACTOR (DINOv2)
# ------------------------------------------------------------
# DINOv2 (Oquab et al., 2023 - arXiv:2304.07193)
# The similarity between two images is the COSINE between their embeddings

MODEL_NAME = "facebook/dinov2-base"

# Device: GPU if available, otherwise CPU
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# How many pairs to show in the printed ranking / markdown
TOP_N = 50


# ============================================================
# READING THE TRAINING SPLIT IMAGES
# ============================================================

def load_train_list():
    """Reads data.yaml and lists the training split images."""

    with open(DATA_YAML, "r", encoding="utf-8") as f:
        cfg = yaml.safe_load(f)

    base = Path(cfg["path"])
    train_dir = base / cfg["train"]

    extensions = {
        ".jpg", ".jpeg", ".png",
        ".bmp", ".tif", ".tiff",
    }

    images = sorted(
        img
        for img in train_dir.iterdir()
        if img.is_file()
        and img.suffix.lower() in extensions
    )

    if not images:
        raise FileNotFoundError(
            f"No training image found in: {train_dir}"
        )

    return images


# ============================================================
# EMBEDDING EXTRACTION (DINOv2)
# ============================================================

def extract_embeddings(images):
    """
    Passes each image through DINOv2 and extracts the global embedding. 
    
    Returns an (N, D) matrix of embeddings already normalized
    """

    print(f"Loading model {MODEL_NAME} on {DEVICE}...")

    processor = AutoImageProcessor.from_pretrained(MODEL_NAME)
    model = AutoModel.from_pretrained(MODEL_NAME).to(DEVICE)
    model.eval()

    vectors = []

    print(f"Extracting embeddings from {len(images)} images...")

    with torch.no_grad():
        for idx, path in enumerate(images, start=1):

            image = Image.open(path).convert("RGB")

            inputs = processor(images=image, return_tensors="pt")
            inputs = {k: v.to(DEVICE) for k, v in inputs.items()}

            output = model(**inputs)

            # CLS token = global image embedding
            cls = output.last_hidden_state[:, 0, :]

            # L2 normalize (inner product == cosine)
            cls = torch.nn.functional.normalize(cls, p=2, dim=1)

            vectors.append(cls.cpu().numpy()[0])

            if idx % 50 == 0:
                print(f"  {idx}/{len(images)} images...")

    return np.vstack(vectors).astype(np.float32)


# ============================================================
# COSINE COMPARISON (all pairs)
# ============================================================

def compare_all(images, embeddings):
    """
    Computes the cosine similarity for all possible pairs
    (N*(N-1)/2) and returns the list ordered from the MOST
    similar to the LEAST similar pair.
    """

    names = [img.name for img in images]
    n = len(names)
    total_pairs = n * (n - 1) // 2

    print(f"Comparing {total_pairs} pairs via cosine...")

    results = []
    done = 0

    for i, j in combinations(range(n), 2):

        # Embeddings already normalized -> inner product = cosine
        score = float(np.dot(embeddings[i], embeddings[j]))

        results.append(
            {
                "image_a": names[i],
                "image_b": names[j],
                "cosine": round(score, 4),
            }
        )

        done += 1
        if done % 5000 == 0:
            print(f"  {done}/{total_pairs} pairs...")

    # Sort from most similar to least similar
    results.sort(key=lambda r: r["cosine"], reverse=True)

    return results


# ============================================================
# OUTPUTS (CSV + MARKDOWN)
# ============================================================

def save_csv(results, csv_path):

    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=["image_a", "image_b", "cosine"],
        )
        writer.writeheader()
        writer.writerows(results)


def save_markdown(results, md_path, top_n):

    lines = []
    lines.append(
        "# Similarity Ranking (DINOv2 embeddings) - training"
    )
    lines.append("")
    lines.append(
        f"Cosine similarity between embeddings extracted "
        f"with {MODEL_NAME}."
    )
    lines.append("")
    lines.append(f"## Top {top_n} most similar pairs")
    lines.append("")
    lines.append("| # | Image A | Image B | Cosine |")
    lines.append("|---|---|---|---|")

    for pos, r in enumerate(results[:top_n], start=1):
        lines.append(
            f"| {pos} | {r['image_a']} | "
            f"{r['image_b']} | {r['cosine']:.4f} |"
        )

    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


# ============================================================
# CHARTS
# ============================================================

def generate_charts(results, out_dir, top_n):

    scores = [r["cosine"] for r in results]

    # --------------------------------------------------------
    # 1) Distribution (histogram) of cosine scores
    # --------------------------------------------------------

    fig, ax = plt.subplots(figsize=(10, 6))

    ax.hist(scores, bins=50, color="#4C72B0", edgecolor="black")
    ax.set_title(
        "Distribution of cosine similarity between pairs",
        fontsize=14,
        fontweight="bold",
    )
    ax.set_xlabel("Cosine")
    ax.set_ylabel("Number of pairs")
    ax.grid(axis="y", linestyle="--", alpha=0.4)

    fig.tight_layout()
    path_hist = out_dir / "distribuicao_cosseno.png"
    fig.savefig(path_hist, dpi=150)
    plt.close(fig)

    # --------------------------------------------------------
    # 2) Horizontal bars with the top-N most similar pairs
    # --------------------------------------------------------

    top = results[:top_n]

    labels = [
        f"{r['image_a']}\n{r['image_b']}"
        for r in top
    ]
    values = [r["cosine"] for r in top]

    height = max(6, len(top) * 0.35)
    fig, ax = plt.subplots(figsize=(10, height))

    positions = range(len(top))
    ax.barh(list(positions), values, color="#55A868")

    ax.set_yticks(list(positions))
    ax.set_yticklabels(labels, fontsize=7)
    ax.invert_yaxis()  # most similar on top
    ax.set_xlabel("Cosine")
    ax.set_xlim(0, 1)
    ax.set_title(
        f"Top {top_n} most similar pairs (DINOv2 embeddings)",
        fontsize=14,
        fontweight="bold",
    )
    ax.grid(axis="x", linestyle="--", alpha=0.4)

    fig.tight_layout()
    path_top = out_dir / "top_pares_cosseno.png"
    fig.savefig(path_top, dpi=150)
    plt.close(fig)

    return [path_hist, path_top]


# ============================================================
# EXECUTION
# ============================================================

def main():

    if not DATA_YAML.exists():
        raise FileNotFoundError(
            f"data.yaml not found: {DATA_YAML}\n"
            "Run prepare_yolo_dataset.py first."
        )

    PROJECT_DIR.mkdir(parents=True, exist_ok=True)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out_dir = PROJECT_DIR / f"embedding_{timestamp}"
    out_dir.mkdir(parents=True, exist_ok=True)

    images = load_train_list()

    embeddings = extract_embeddings(images)

    results = compare_all(images, embeddings)

    top_n = min(TOP_N, len(results))

    # --------------------------------------------------------
    # RANKING IN THE TERMINAL
    # --------------------------------------------------------

    print("\n" + "=" * 70)
    print(f"SIMILARITY RANKING (top {top_n} pairs)")
    print("=" * 70)

    print(f"{'#':>3}  {'Cosine':>8}  Pair")
    print("-" * 70)

    for pos, r in enumerate(results[:top_n], start=1):
        print(
            f"{pos:>3}  {r['cosine']:>8.4f}  "
            f"{r['image_a']} <-> {r['image_b']}"
        )

    # --------------------------------------------------------
    # SAVE OUTPUTS
    # --------------------------------------------------------

    csv_path = out_dir / "embedding_pares.csv"
    md_path = out_dir / "embedding_ranking.md"

    save_csv(results, csv_path)
    save_markdown(results, md_path, top_n)

    charts = generate_charts(results, out_dir, top_n)

    # Also save the embeddings (useful for reuse/analysis)
    np.save(
        out_dir / "embeddings.npy",
        embeddings,
    )

    # --------------------------------------------------------
    # STATISTICAL SUMMARY
    # --------------------------------------------------------

    scores = np.array([r["cosine"] for r in results])

    print("\n" + "=" * 70)
    print("SUMMARY")
    print("=" * 70)
    print(f"Extractor model: {MODEL_NAME}")
    print(f"Images compared: {len(images)}")
    print(f"Pairs evaluated: {len(results)}")
    print(f"Mean cosine:     {scores.mean():.4f}")
    print(f"Median cosine:   {np.median(scores):.4f}")
    print(f"Max cosine:      {scores.max():.4f}")
    print(f"Min cosine:      {scores.min():.4f}")

    print("\n" + "=" * 70)
    print("GENERATED FILES")
    print("=" * 70)
    print(f"CSV (all pairs):    {csv_path}")
    print(f"Markdown (top {top_n}): {md_path}")
    for c in charts:
        print(f"Chart:              {c}")
    print(f"Embeddings (.npy):  {out_dir / 'embeddings.npy'}")
    print("=" * 70)


if __name__ == "__main__":
    main()
